INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_description','دليل AFP الشامل لريّ النقاط للمزارعين العراقيين. افهم المبادئ الأساسية، المزايا المالية، ونقاط التنفيذ الرئيسية للمزارع الدقيقة لزيادة إنتاجية المحاصيل في العراق.' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_description');
