INSERT INTO `ha_term_relationships` (`object_id`,`term_taxonomy_id`,`term_order`) SELECT @translation_id,tt.term_taxonomy_id,0 FROM `ha_term_taxonomy` tt JOIN `ha_terms` t ON t.term_id=tt.term_id WHERE @translation_id IS NOT NULL AND tt.taxonomy='category' AND t.slug='en' AND NOT EXISTS (SELECT 1 FROM `ha_term_relationships` r WHERE r.object_id=@translation_id AND r.term_taxonomy_id=tt.term_taxonomy_id) LIMIT 1;
INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<h2>Таърифи баробари оҳуддӣ ва нақши он дар кишоварзии муосир</h2><p>Оҳуддӣ барои намӣ ё идоракунии дақиқи намии хок яке аз мавзӯъҳои мураккаб ва муҳим дар системаҳои оҳуддии қатрагӣ ва шитобдории рақамикӣ аст. Ба фарқ аз бовари оммавӣ, ки оҳуддӣ танҳо барои таъмини оби барг аст, идоракунии намӣ раванди ақлидӯст аст, ки ҳадафаш нигоҳдории мувозинат байни расонишани оксиген ба реша ва таъмини намии кофӣ барои рушд аст. Дар шароити хокҳои сабуку зардӣ, ошободишии зиёди об метавонад ба камнорасии оксигени реша ва дар натиҷа бемории ганҷӣ оварда расонад. Аз ҷониби дигар, дар хокҳои зиракӣ, хушкӣи паст боиси ҷамъшавии об дар сатҳ мегардад ва решаҳои чуқур чидӣ мемонанд.</p><p>Дар ин қисмат аз раҳнамоии ҷумъаи оҳуддии намӣ, диққат ба истифодаи оптималии миқдори ҳосили буғдой ва заҳум дар гектар ҳамчун нишонаи саломатии барг зери таъсири намӣ муроҷиат мешавад. Баргҳое, ки дар шароити оҳуддии намии стандартӣ ҷойгир мешаванд, одатан босуди баландтарро дар воҳиди оби истифодашуда нишон медиҳанд.</p><h3>Фарқияти оҳуддии ҳаҷмӣ ва намӣ</h3><ul><li><strong>Оҳуддии ҳаҷмӣ:</strong> Ҳадафи асосӣ расониши миқдори муаййани об ба замин дар ҳар як доира аст. Ин роҳ осон аст, вале одатан ба зардигишавии зиёдтар ва пардохти об оварда мерасонад.</li><li><strong>Оҳуддии намӣ:</strong> Ҳадаф расидан ба намии оптималӣ дар минтақаи реша (Namии минтақаи реша) аст. Дар ин ҳолат, қароридодии оҳуддӣ бо роҳи санҷиши намии хок ё моделҳои телеметрикӣ сурат мегирад.</li></ul><p>Истифодаи навари чоп барои оғозубии намӣ ба таҳсилоти баланд дар тарроҳӣ ниёз дорад. Зеро сӯрохҳои хурди ин навҳо дар зидди фишор ва шидати майлӣ ҷониби баланд доранд.</p><><h2>Навъҳои навҳоҳои оғозубии қатқатӣ ва сохтори онҳо</h2><p>Интихоби навъи навари чоп ба таври мустақим ба сифати паҳн кардани намӣ дар қабоқҳои гуногуни замин таъсир мерасонад. Навъҳои гуногун мувофиқи содирот, қалафсақӣ, диаметр ва масофаи сӯрохҳо тасниф карда мешаванд. Дар қисмҳои ихтисосии дастраҳи умумии оғозубии намӣ шиносоии техникӣ бо ин маҳсулот ҳарчӣ муҳимтар аст.</p><h3>Навҳоҳои пайваста (Laminated) ва ягонақабата (Mono-wall)</h3><ol><li><strong>Навҳоҳои пайваста:</strong> Сохтори бисёрқабата доранд ва аз ҷиҳати механикӣ мустаҳкамтаранд. Барои киштҳои бо дебитҳои паст ва ниёзи дақиқи об (масалан, домнаи сабзотӣ) мувофиқанд. Зиддикории баландтарии пайвастагии решаҳо доранд.</li><li><strong>Навҳоҳои ягонақабата:</strong> Нарм ва хомӯшанд. Нархҳояшон паст аст ва барои киштҳои фаслӣ бо фоидаи кӯтоҳмуддат (масалан, каҳӯ ё спанидж) идеалӣ мебошанд. Дар оғозубии намӣ ин навҳо бояд дар ҳар фасл иваз карда шаванд, то ки маҳкамшавӣ ва тағйироти шакл пешгирӣ карда шавад.</li></ol><p>Барои ошноӣ бо ҷузъияти технӣкӣ, омӯзиш <a href="https://navar-abyari.ir/%D8%A7%D9%86%D9%88%D8%A7%D8%B9-%D9%86%D9%88%D8%A7%D8%B1-%D8%A2%D8%A8%DB%8C%D8%A7%D8%B1%DB%8C-%D9%88-%D8%B9%D9%85%D9%84%DA%A9%D8%B1%D8%AF-%D9%87%D8%B1%DA%A9%D8%AF%D8%A7%D9%85/">Намҳои анбӯри абириш ва кори ҳар яки онҳо</a> Тавсия карда мешавад. Интихоби анбӯри бо диаметри мувофиқи сӯрох (масалан, аз 1.6 миллиметр то бештар) барои кам кардани ҷамъшавии ионҳои кальсий ва магний дар системаи абириш намкиҳо зарур аст.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/راهنمای-جامع-آبیاری-رطوبتی-تصویر-شاخص.webp" alt="راهنمای جامع آبیاری رطوبتی - تصویر 1"/><figcaption>Абриши намкиҳо comprehensive guide</figcaption></figure><h3>Анбӯрҳои зериръӣ</h3><p>Яке аз пешрафта ҷиҳазҳои абриши намкиҳо истифодаи анбӯрҳои зериръӣ аст, ки дар ҳанъаги решаҳо (одатан 10 то 20 сантиметр зер сатҳ) карда мешаванд. Ин усул бухоршавиро ба сифр мерасонад ва идоракунии дақиқтари намкиҳоро пешниҳод мекунад. Бо вуҷуди ин, насби онҳо мураккабтар аст ва ба таҷҳизоти муҳандисӣ ниёз дорад. Агар замини шумо бо оби сахт мухоҳид бошад, баррасӣ <a href="https://navar-abyari.ir/%d9%87%d9%85%d9%87-%da%86%db%8c%d8%b2-%d8%af%d8%b1%d8%a8%d8%a7%d8%b1%d9%87-%d8%a2%d8%a8%db%8c%d8%a7%d8%b1%db%8c-%d8%b2%db%8c%d8%b1%d8%b3%d8%b7%d8%ad%db%8c/">Ҳама чиз дар бораи абриши зериръӣ</a> метавонад меъёрҳои тарроҳии мувофиқро равшан кунад.</p><><h2>Маслиҳотҳои амалӣ барои идоракунии намнокӣ бо ларинг тиб</h2><p>Иҷрои дурусти обории намнокӣ риояи дастурамалҳои мушаххаси амалӣро талаб мекунад. Дар поён муҳимтарин нуқтаҳое мебошанд, ки кишоварон ҳангоми нақшакшии обориш бояд риоя кунанд.</p><h3>1. Танзими фишори система</h3><p>Дар обории намнокӣ бо ларинг тиб фишори вориди ларинг бояд бо дақиқӣ назорат карда шавад. Агар фишор аз ҳадди ҳадди ақал камтар бошад, ларинг метавонад бурбутад шавад ва пардохти баробарпаймони обро маҳв кунад. Аз тарафи дигар, фишори зиёд боиси фарсӯдии деворҳои ларинг ва тағйирёбии диаметри сӯроҳҳо мегардад. Тавсия мешавад, ки дар оғози ларинг аз сарпӯши чек-валасти (check-valve) истифода вард, токи ҷараёни устувор таъмин гардад.</p><h3>2. Майлории пойдаякӣ</h3><p>Ларинг тиб ба майлори замин хеле ҳассос аст. Тами майлорҳои дақиқ метавонанд боиси ҷамъшавии об дар поёнҳои ларинг ва камшавии об дар болотарин қисматҳо гарданд. Дар заминҳои майлордӯшт бояд аз ларингҳое, ки сардодиши баландтар доранд, ё аз чанд ларинги пайдарпаи дар самти майлории замин барои ҷӯборкунии фарқияти фишор истифода вард.</p><h3>3. Идоракунии маводи гизоӣ (Фитигатсия)</h3><p>Яке аз бартарияҳои обории намнокӣ имконияти муттаҳид кардан бо гизокунии маҳлулпаршӣ мебошад. Вақте ки аз одагон дар системаи обориш истифода мебаранд, аз хомӯшшавии минералҳо пешгирӣ кунед. Масалан, маҳлулҳои версаҷ ва калсий бо ҳам омадан меафкананд. Агар аз ларингҳое, ки сӯроҳҳои хурд доранд, истифода варда мешавед, ҳатман аз филтри мувофиқ (торӣ ё дискӣ) истифода вард. Хондани дастурамали ихтисосӣ <a href="https://navar-abyari.ir/ppriq-ca-drip-irrigation-guide/">Рӯшноии махсуси ppriq ca drip irrigation</a> Метавонад дар пешгирӣ аз дорсидани сӯрохҳо аз сабаби рамли карбонати калсий самаранок бошад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/راهنمای-جامع-آبیاری-رطوبتی-کاربرد-عملی.webp" alt="راهنمای جامع آبیاری رطوبتی - تصویر 2"/><figcaption>Ориғии бағӣ comprehensive guide</figcaption></figure><h3>4. Сикли бағӣ</h3><p>Дар ориғии бағӣ сикли бағӣ кӯтоҳ ва такрорӣ аст (масалан, ҳар рӯз ё ҳар ду рӯз). Ин усул боиси он мегардад, ки решаҳо бо маҷбурӣ амиқтар шаванд ва самаранокии системаи решаҳо беҳтар гардад. Инчунин, он аз хушк шудани пурраи профили решаҳо пешгирӣ мекунад, ки барои растаниҳо ба фишори хушкӣ ҳассос лозим аст.</p><h2>Дастаррасӣ ва зичии кортукронӣ дар ориғии бағӣ</h2><p>Фосила байни ҷуръатҳо ва нӯрҳои бағӣ дар ориғии бағӣ нақши ҳайтиро дар меёбад. Агар фосилаи ҷуръатҳо зиёд бошад, зони бағӣ байни ҷуръатҳо кам мегардад ва решаҳои канорӣ хушк мешаванд. Агар фосила коҳиш дода шавад, имконияти ҷамъшавии об ва пайдоиш нокомии оксиген мавҷуд аст.</p><h3>Ҳисобкунии зичии бадир</h3><p>Барои беҳтар кардани самаранокии кор, зичии ғунӣ бояд бо имконияти осёбшавии парчами капельӣ мувофиқ карда шавад. Растаниҳои зич осёбшавии бештарро талаб мекунанд. Шумо метавонед тавассути омӯзиши роҳнамо оид ба ҳосили сорго дар гектар: омилҳои таъсиррасон ва ҳалҳо фаҳмиши беҳтари робита байни зичӣ ва эҳтиёҷи об дар растаниҳои ғаллакӯш пайдо кунед. Агар майдонҳои гӯдаки томати ё картошкаро дошта бошед, принсипҳои монан ба ҳисоб кардани зичии қаламфури ё дигар сабзавоти шитобӣ низ дахл доранд.</p><h3>Парчами капельӣ дар коркунҳои мушаххас</h3><p>Дар коркунҳои бо ошмоиши тез, монанди кашел (латучия) ё спарҳавчак (спарҳавчак/шпинат), парчами капельӣ бояд дақиқан зери хати ошмоиш ҷойгир шавад. Дар дарахтон, масофаи парча аз қадам бояд кофӣ бошад, то нам бевосита ба қадам нарасад ва сӯхтани қадамро ба миён наоварад. Одатан масофаи 15 то 20 см тавсия дода мешавад.</p><><h2>Саволҳои маъмулӣ (FAQ)</h2><h3>Оё парчами капельӣ пас аз мавсим баргаштан мумкин аст?</h3><p>Бале, парчами ягонақабата (Mono-wall) одатан қобилияти ҷамъ ва баргашт доранд ва барои мавсими навбат коркардӣ барои истифодаи дубора мувофиқанд, шарт он ки шустан ва барқарор кардани онҳо ба хубӣ иҷро шуда бошад. Парчами ламинатшуда (Laminated) муқовимати механикии баландтар доранд ва умри хизматрасонии тӯлонитар доранд, бинобар ин баргаштани онҳо ба андозаи парчами ягонақабата маъмул нест ва одатан дар боғҳои дарахтӣ ба таври доимӣ зер сатҳи хок ҷойгир карда мешаванд.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/راهنمای-جامع-آبیاری-رطوبتی-جزئیات-فنی.webp" alt="راهنمای جامع آبیاری رطوبتی - تصویر 3"/><figcaption>Осёбшавии намнокунӣ - роҳнамои умумӣ</figcaption></figure><h3>Беҳтарин вақти осёбшавии намнокунӣ бо парчами капельӣ чӣ соате аст?</h3><p>Вобаста ба намуди оштор ва шароити иқлим, вақтҳои гуногун дорад. Дар минтақаҳои гарм ва хушк, овардани обро дар субҳи зود ё шомир то шаб (баъд аз офтобшурӯъ) тавсия мекунанд, то табуи коҳиш ёбдад. Дар минтақаҳои мулоим, овардани об соати 9 то 11-и субҳ низ қабул аст. Нуктаи калидӣ ин аст, ки дар оварданиоби ғарқобӣ ҳадаф расидан ба таркиши мувофиқ аст, на тар шудани пурраи сатҳи хок, бинобар ин тағйироти ҳарорати ҳавоӣ дар вақти овардани об нисбат ба усулҳои пӯшобӣ аҳамияти камтар дорад.</p><h3>Чӣ бароири ранги пипр бо сӯрохҳои 1/4 дюйм барои ошторҳои ҳассос вуҷуд дорад?</h3><p>Сӯрохҳои хурдтар ҳаҷми обпечушро камтар мебароянд ва барои ошторҳои ҳассос ба фишори решаҳо ё дарахтони ҷавон мувофиқтаранд, зеро шустани об камтар аст ва аз ҷамъшавии об дар беруни минтақаи решаҳо пешгирӣ мекунад. Ҳамин тавр, ин сӯрохҳо бештар дар сатҳи гирифтгӣ қобилият доранд ва ба филтратсияи дақиқтар ниёз доранд. Агар дар минтақаи шумо об даринки сахт бошад, пеш аз харид, ҳатман бо фурӯшанда муштариёрӣ кунед, то нишони сӯрохҳо бо стандартҳои минтақа мутобиқ шаванд.</p><h2>Хулосабарорӣ ва раҳокунии ниҳоӣ</h2><p>Оварданиоби ғарқобӣ бо ранги пипр раванди динамикӣ аст, ки ба назорати давомдар меистид. Муваффақият дар ин усул дарккунии амиқи робитаи байни намуди хок, зичии кишоварзӣ ва фишори системаи навозишро талаб мекунад. Бо пайравӣ ба нуктаҳои амалии дар қисмҳои махсусии дастураи ҷамъбасти оварданиоби ғарқобӣ овардашуда, метавонед истеъмоли обро коҳиш диҳед ва ҳосилилоҳаро ба ҳадди авҷ барсоред.</p><ul><li>Аз рангҳо бо оқибши сӯрох мувофиқ бо сифати оби худ истифода баред.</li><li>Рангҳоро бо муҳимми камтар аз 3% дар самти муҳимм ҷойгир кунед.</li><li>Филтратсияро ҳеҷ гоҳ диққат надиҳед; ин муҳимтарин қисми нигоҳубини система аст.</li><li>Барои парҳаҳо дар тӯли ҷамъоварии дарозмуддат, ба ҳалли зерзамина ё ҷануби ғайричаспандагӣ диққат диҳед.</li></ul><p>Дар натиҷа, барои гирифтани илҳоҳои бештар дар бораи интихоби ҷиҳози асосӣ мувофиқ, ки бо наварҳои ҷабиш ва мувофиқатии фишор доранд, шумо метавонед ба дастоварди <a href="https://navar-abyari.ir/intihob-lanti-tezrandaa-baroi-kishovarzi/">интихоби ҷиҳози Т-шакл барои кишоварзӣ</a> муроҷиат кунед. Тавофиқи дурусти ҷиҳози асосӣ ва наварҳои шохӣ оморгириш барои системаи обёрони ғиёзи самаранок аст.</p>','Комилнагрудии иро обӣ: асосҳо, амалияту амалӣ ва бартарӣ додан дар нухати чидун','Ошноӣ бо асосҳои обёрӣи намнокӣ дар системаҳои тармаи типӣ, баррасии омилҳои калидӣ, ба монанди чурунишобии қатъшавӣ, масоҳати тармаҳо ва идоракунии фишори система. Ин мақола ҳамчун манбаи фарҳанги барои оптимизатсияи сарфи об дар кишоварзии сабззавот, ғалладонаҳо ва набототи дорӣ пешниҳод шудааст.','publish','closed','closed','kimilonagudi-iro-obi-tajik',NOW(),UTC_TIMESTAMP(),0,'',0,'post','',0 WHERE @source_post_id IS NOT NULL AND @translation_id IS NULL AND @slug_conflict IS NULL;
