INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_title','دليل ري البيوت البلاستيكية في العراق: اختيار وتنسيق أنظمة التنقيط والخطوط المسطحة لتحسين المحاصيل' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_title');
INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_description','تعرف على المبادئ الأساسية لتكامل أنظمة الري بالتنقيط والخطوط المسطحة في البيوت البلاستيكية. دليل عملي للمزارعين العراقيين لاختيار وتحسين كفاءة الري والحد من هدر المياه.' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_description');
