INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_title','دليل المزارع العراقي للتوافق بين شريط التنقيط المثبت وشريط التنقيط | الكفاءة الزراعية' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_title');
INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_description','دليل تقني شامل يشرح توافق شريط التنقيط المثبت مع أنظمة التنقيط في العراق، مع نصائح للتركيز الأمثل، تحسين توزيع المياه، وتقليل المخاطر الزراعية للمزارعين.' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_description');
